import asyncio
import os
import httpx
from .config import API_BASE_URL, DATASET_DIR

async def create_world(client: httpx.AsyncClient) -> str:
    print("Creating Benchmark World...")
    response = await client.post(
        f"{API_BASE_URL}/worlds",
        json={
            "name": "Automated Benchmark World",
            "description": "World automatically generated by the benchmarking suite."
        }
    )
    response.raise_for_status()
    world_id = response.json()["id"]
    print(f"World created with ID: {world_id}")
    return world_id

async def upload_document(client: httpx.AsyncClient, world_id: str, filepath: str) -> dict:
    print(f"Uploading {os.path.basename(filepath)}...")
    with open(filepath, "rb") as f:
        files = {"file": (os.path.basename(filepath), f, "text/markdown")}
        data = {"world_id": world_id}
        response = await client.post(
            f"{API_BASE_URL}/documents/worlds/{world_id}/upload",
            data=data,
            files=files,
            timeout=300.0
        )
        response.raise_for_status()
        doc = response.json()
        print(f"Successfully uploaded {doc['filename']} (ID: {doc['id']})")
        return doc

async def generate_world_and_upload() -> tuple[str, list[dict]]:
    async with httpx.AsyncClient(timeout=300.0) as client:
        world_id = await create_world(client)
        
        md_files = list(DATASET_DIR.glob("*.md"))
        if not md_files:
            print("No markdown files found in datasets directory. Run dataset_loader first.")
            return world_id, []
            
        docs = []
        # Upload sequentially to avoid overloading the ingest queue abruptly,
        # though concurrency could be used.
        for file in md_files:
            doc = await upload_document(client, world_id, str(file))
            docs.append(doc)
            
        print("World generation and document upload complete.")
        return world_id, docs

if __name__ == "__main__":
    asyncio.run(generate_world_and_upload())
